/** Functions whose live definition still raises ERRCODE 'P0002'. EXACT, both ways. */
const P0002_RAISERS = 52;
/**
 * Refusals that used P0002 but name a state, not a missing row: they move to '22023' (400), never PT404 (lead 11-03).
 * Function -> the exception message it raises with '22023'.
 */
const STATE_REFUSALS: [string, string][] = [
  ["rentals_confirm_visit", "no_visit_proposed"],
  ["rentals_admin_review_landlord_id", "not_pending_review"],
  ["declutter_admin_review_item", "item_not_pending"],
];

const defs = effectiveDefs(join(process.cwd(), "supabase/migrations"));
const body = (name: string) => blankSqlComments(defs.get(name)?.stmt ?? "");
const RAISES_P0002 = /ERRCODE\s*=\s*'P0002'/i;

/**
 * Edge functions that turn an RPC's SQLSTATE into their own HTTP status. Each one that answers P0002 as 404 must
 * answer PT404 as 404 too, or a moved function's not-found turns into that map's fallback (409). EXACT, both ways:
 * the edge functions still mapping P0002 only. Packet 17 moved declutter-checkout, packet 18 shop-checkout.
 */
const EDGE_MAPS_WITHOUT_PT404: string[] = [];
const FN_DIR = join(process.cwd(), "supabase/functions");
const edgeMaps = readdirSync(FN_DIR)
  .filter((dir) => existsSync(join(FN_DIR, dir, "index.ts")))
  .map((dir) => ({ dir, src: blankComments(readFileSync(join(FN_DIR, dir, "index.ts"), "utf8")) }))
  .filter(({ src }) => /code\s*===\s*"P0002"/.test(src));

describe("not found answers 404 (Q2390)", () => {
  it("reads every function's live definition (inventory floor)", () => {
    expect(defs.size).toBeGreaterThan(1000);
  });

  it("each moved function raises PT404 and no P0002", () => {
    for (const name of MOVED) {
      expect(defs.has(name), name).toBe(true);
      expect(body(name), name).toMatch(/ERRCODE\s*=\s*'PT404'/);
      expect(body(name), name).not.toMatch(RAISES_P0002);
    }
  });

  it("state refusals that left P0002 raise '22023', not PT404 (lead 11-03)", () => {
    expect(STATE_REFUSALS.length).toBeGreaterThan(0);
    for (const [name, message] of STATE_REFUSALS) {
      const re = new RegExp(`RAISE\\s+EXCEPTION\\s+'${message}'\\s+USING\\s+ERRCODE\\s*=\\s*'([^']+)'`, "gi");
      const src = body(name);
      const codes: string[] = [];
      for (let m = re.exec(src); m; m = re.exec(src)) codes.push(m[1]);
      expect(codes.length, `${name} ${message}`).toBeGreaterThan(0);
      expect([...new Set(codes)], `${name} ${message}`).toEqual(["22023"]);
    }
  });

  it(`functions still raising P0002 are exactly ${P0002_RAISERS} (Q2390 ratchet)`, () => {
    const left = [...defs.keys()].filter((name) => RAISES_P0002.test(body(name)));
    expect(left.length).toBe(P0002_RAISERS);
  });

  it("every edge function that answers P0002 as 404 answers PT404 as 404 too (except the exact list still to move)", () => {
    expect(edgeMaps.length).toBeGreaterThan(1);
    const without = edgeMaps.filter(({ src }) => !/code\s*===\s*"PT404"\s*\?\s*404/.test(src)).map(({ dir }) => dir).sort();
    expect(without).toEqual(EDGE_MAPS_WITHOUT_PT404);
  });
});
